NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Hosea'

CHAPTERS = {
    1: {
        1: 'Das Wort Jehovahs, das geschah an Hoschea, den Sohn Beeris, in den Tagen Ussijahs, Jothams, Achas, Jechiskijahs, der Könige Jehudahs, und in den Tagen Jerobeams, des Sohnes von Tagen Jerobeams, König von Israel.',
        2: 'Anbeginn dessen, was Jehovah redete durch Hoschea. Und Jehovah sprach zu Hoschea: Gehe, nimm dir ein Weib der Buhlereien und Kinder der Buhlereien, denn das Land buhlt hinweg von Jehovah.',
        3: 'Und er ging hin und nahm Gomer, Tochter Diblajims, und sie empfing und gebar ihm einen Sohn.',
        4: 'Und Jehovah sprach zu ihm: Nenne seinen Namen Jisreel; denn noch um ein Kleines, so suche Ich das Blut Jisreels am Hause Jehus heim und mache ein Ende mit dem Reiche des Hauses Israel.',
        5: 'Und am selbigen Tage soll es geschehen, daß Ich den Bogen Israels zerbreche im Talgrund Jisreel.',
        6: 'Und sie empfing wieder und gebar eine Tochter; und Er sprach zu ihm: Nenne ihren Namen Lo-Ruchamah; denn Ich erbarme Mich fortan nicht mehr des Hauses Israel, daß Ich ihnen verzeihe.',
        7: 'Des Hauses Jehudah aber erbarme Ich Mich und rette sie durch Jehovah, ihren Gott; und Ich helfe ihnen, nicht durch Bogen und durch Schwert und durch Streit, durch Rosse und durch Reiter.',
        8: 'Und sie entwöhnte Lo-Ruchamah, und empfing und gebar einen Sohn.',
        9: 'Und Er sprach: Nenne seinen Namen Lo-Ammi; denn ihr seid nicht Mein Volk; und Ich werde nicht der eurige sein.',
    },
    2: {
        1: 'Aber die Zahl der Söhne Israels wird sein wie der Sand des Meeres, den man nicht messen und nicht zählen kann; und am Orte, da man zu ihnen sagte: Ihr seid nicht Mein Volk, wird man zu ihnen sagen: Söhne des lebendigen Gottes.',
        2: 'Und es werden sich zusammentun die Söhne Jehudahs und die Söhne Israels allzumal, und ein Haupt über sich setzen und aus dem Lande heraufziehen; denn groß wird sein der Tag Jisreels.',
        3: 'Sprechet zu euren Brüdern: Ammis, und zu euren Schwestern: Ruchamah.',
        4: 'Hadert mit eurer Mutter, hadert, denn sie ist nicht Mein Weib, und Ich nicht ihr Mann, auf daß sie ihre Buhlereien wegtue von ihrem Angesicht, und ihre Ehebrecherei von ihren Brüsten.',
        5: 'Auf daß Ich sie nicht nackt ausziehe und hinstelle wie am Tage, da sie geboren ward, und sie mache wie die Wüste, und sie hinsetze wie ein dürres Land, und lasse sie sterben vor Durst;',
        6: 'Und Ich Mich ihrer Söhne nicht erbarme, darum, daß sie Söhne der Buhlereien sind.',
        7: 'Denn gebuhlt hat ihre Mutter und Schändliches tut, die sie empfangen hat. Denn sie sprach: Ich will gehen hinter meinen Liebhabern her, die mir geben mein Brot und mein Wasser, meine Wolle und mein Linnen, mein Öl und mein Getränk.',
        8: 'Darum siehe, Ich umhege deinen Weg mit Dornen, und ummauere dich mit einer Mauer, daß deine Steige du nicht finden sollst.',
        9: 'Und sie setzt ihren Liebhabern nach, aber kann sie nicht erreichen, und sucht sie, aber findet sie nicht; da spricht sie: Ich will gehen und zurückkehren zu meinem ersten Manne; denn besser war es mir da, als jetzt.',
        10: 'Und sie wußte nicht, daß Ich ihr gab das Korn und den Most und das Öl, und ihr das Silber mehrte und das Gold, das sie ihrem Baale machten.',
        11: 'Darum will Ich zurückkehren und zu seiner Zeit nehmen Mein Korn und Meinen Most zu seiner bestimmten Zeit, und ihr entreißen Meine Wolle und Mein Linnen, womit sie ihre Blöße deckt.',
        12: 'Und nun will Ich ihre Torheit aufdecken vor den Augen ihrer Liebhaber, und kein Mann soll sie aus Meiner Hand entreißen.',
        13: 'Und Ich will ein Ende machen all ihrer Freude, ihrem Feste, ihrem Neumond und ihrem Sabbath und all ihrem Feiertage.',
        14: 'Und will verwüsten ihren Weinstock und ihren Feigenbaum, von denen sie sagte: Sie sind eine Buhlgabe mir, die meine Liebhaber mir gegeben; und setze sie zum Walde, daß das wilde Tier des Feldes sie frißt;',
        15: 'Und will heimsuchen an ihr die Tage der Baale, an denen sie ihnen räucherte, und sich schmückte mit ihrem Nasenreif und ihrem Geschmeide, und ihren Liebhabern nachging, und Mein vergaß, spricht Jehovah.',
        16: 'Darum siehe, Ich will sie bereden und in die Wüste bringen und ihr ans Herz reden.',
        17: 'Und Ich will ihr von da ihre Weinberge und den Talgrund Achor zur Pforte der Hoffnung geben; und sie wird singen dort wie in den Tagen ihrer Jugend, und wie am Tage ihres Heraufziehens aus dem Lande Ägypten;',
        18: 'Und es soll geschehen an jenem Tage, daß du Mich nennen wirst: Mein Mann, und wirst Mich nicht mehr mein Baal nennen.',
        19: 'Und Ich will die Namen der Baale aus ihrem Munde wegtun, und sie sollen ihres Namens nicht mehr gedenken.',
        20: 'Und Ich will ihnen an jenem Tage einen Bund schließen mit dem wilden Tier des Feldes, und mit dem Gevögel der Himmel und dem Kriechtier des Bodens, und will Bogen und Schwert und Streit zerbrechen von der Erde, und lasse sie in Sicherheit niederliegen.',
        21: 'Und will dich mit Mir verloben in Ewigkeit, und dich Mir verloben in Gerechtigkeit und in Gericht, und in Barmherzigkeit und in Erbarmen.',
        22: 'Und werde dich Mir verloben in Treue, und du sollst Jehovah erkennen.',
        23: 'Und soll geschehen am selbigen Tage, daß Ich erhöre, spricht Jehovah, daß Ich erhöre die Himmel und sie werden erhören die Erde, Und die Erde soll erhören das Korn und den Most und das Öl, und diese erhören Jisreel. Und Ich will sie Mir säen im Lande, und will Mich erbarmen der Lo-Ruchamah, und sprechen zu Lo-Ammi: Mein Volk bist du, und es wird sprechen: Mein Gott!',
    },
    3: {
        1: 'Und Jehovah sprach zu mir: Gehe abermals hin, liebe ein Weib, das von einem Genossen geliebt wird und Ehebruch treibt, wie Jehovah die Söhne Israels liebt, sie aber wenden sich anderen Göttern zu und lieben Kuchen von Weinbeeren.',
        2: 'Und ich erkaufte sie mir um fünfzehn Silberlinge und einen Chomer Gerste und einen Lethech Gerste.',
        3: 'Und ich sprach zu ihr: Viele Tage sollst du bei mir wohnen; du sollst nicht buhlen und sollst keines Mannes sein, und auch ich will dein sein.',
        4: 'Denn viele Tage werden die Söhne Israels wohnen ohne König, und ohne Obersten, und ohne Opfer, und ohne Denksäule, und ohne Ephod und Theraphim.',
        5: 'Danach werden die Söhne Israels zurückkehren und suchen Jehovah, ihren Gott, und David, ihren König, und mit Schauern kommen zu Jehovah und zu Seinem Guten, in den letzten der Tage.',
    },
    4: {
        1: 'Höret, ihr Söhne Israels, das Wort Jehovahs; denn einen Hader hat Jehovah mit denen, die im Lande wohnen, darum, daß keine Wahrheit und keine Barmherzigkeit und keine Kenntnis Gottes im Lande ist.',
        2: 'Eide und Verleugnung, und Morden und Stehlen und Ehebruch brechen hervor, und Blut reicht an Blut.',
        3: 'Darum trauert das Land und verschmachtet alles, das darin wohnt, beim wilden Tier des Feldes, und beim Gevögel der Himmel; und auch die Fische des Meeres werden hingerafft.',
        4: 'Nur hadere der Mann nicht, noch strafe der Mann; und dein Volk ist wie solche, die mit dem Priester hadern.',
        5: 'Und du strauchelst am Tage, und auch der Prophet strauchelt in der Nacht mit dir, und deine Mutter lasse Ich untergehen.',
        6: 'Mein Volk geht unter, weil es ohne Kenntnis ist; weil du die Kenntnis verschmäht hast, will auch Ich dich verschmähen, daß du nicht mehr Mein Priester seiest, und weil du das Gesetz deines Gottes vergaßest, will auch Ich deine Söhne vergessen.',
        7: 'Je mehr ihrer wurden, desto mehr sündigten sie wider Mich; ihre Herrlichkeit will Ich in Unehre umwandeln.',
        8: 'Sie essen Meines Volkes Sündopfer, und nach ihrer Missetat erheben sie ihre Seele.',
        9: 'Darum soll es mit dem Volk sein wie mit den Priestern, und Ich will seine Wege an ihm heimsuchen und nach seinem Handeln ihm zurückgeben.',
        10: 'Und sie sollen essen und nicht satt werden, und sie werden buhlen, und doch nicht sich ausbreiten, darum, daß sie unterließen, auf Jehovah zu halten.',
        11: 'Buhlerei und Wein und Most hat ihr Herz eingenommen.',
        12: 'Mein Volk befragt sein Holz, und sein Stock sagt ihm an; denn der Geist der Buhlereien hat es irregeführt; und sie buhlen weg von ihrem Gotte.',
        13: 'Auf den Gipfeln der Berge opfern sie und räuchern auf den Hügeln, unter der Eiche und der Weißpappel und Steineiche; denn gut ist ihr Schatten. Darum buhlen eure Töchter, und eure Schnüre treiben Ehebruch.',
        14: 'Nicht will Ich es heimsuchen an euren Töchtern, daß sie buhlen, und an euren Schnüren, daß sie ehebrechen; denn sie selbst trennen sich ab mit Buhlerinnen, und opfern mit Tempeldirnen; und das unverständige Volk wird zu Fall gebracht.',
        15: 'Wenn du buhlst, Israel, so verschulde sich doch Jehudah nicht. Und laß sie nicht kommen nach Gilgal und nicht hinaufgehen gen Beth-Aven, und nicht schwören: Beim Leben Jehovahs.',
        16: 'Denn wie eine störrische Kuh ist störrisch Israel, nun wird Jehovah sie wie ein Lamm auf weiter Trift weiden lassen.',
        17: 'Ephraim hat sich mit den Götzen verbündet, so lasset ihn!',
        18: 'Ihr Weintrank entweicht, sie haben gebuhlt, sie lieben, ihre Schilde geben Unehre.',
        19: 'Der Wind schnürt sie in seinen Flügeln zusammen, und sie schämen sich ob ihrem Opfern.',
    },
    5: {
        1: 'Höret dies, ihr Priester, und horchet, ihr, o Haus Israel, und du, Haus des Königs; nehmt es zu Ohren; denn für euch ist das Gericht, weil ihr eine Schlinge geworden seid für Mizpah und ein ausgebreitet Netz über Tabor.',
        2: 'Und mit dem Schlachten vertiefen sich die, so sich wegwenden; aber Ich will ihnen allen eine Züchtigung sein.',
        3: 'Ich kenne Ephraim, und Israel ist mir nicht verhohlen; denn du, Ephraim, hast jetzt gebuhlt, Israel hat sich verunreinigt.',
        4: 'Ihre Handlungen gestatteten nicht, zu ihrem Gotte zurückzukehren; denn der Geist der Buhlereien ist in ihrem Inneren, und sie kennen Jehovah nicht.',
        5: 'Und Israels Stolz wird antworten wider sein Angesicht; und Israel und Ephraim werden straucheln durch ihre Missetat; es strauchelt auch Jehudah mit ihnen.',
        6: 'Mit ihrem Kleinvieh und ihren Rindern werden sie kommen, zu suchen Jehovah, und werden Ihn nicht finden; denn Er hat Sich ihnen entzogen.',
        7: 'Dem Jehovah wurden sie untreu; denn fremde Söhne zeugten sie, nun soll sie der Neumond fressen samt ihrem Teile.',
        8: 'Stoßet in die Posaune in Gibeah, in die Trompete in Ramah, blaset Lärm in Beth-Aven, hinter dir her, Benjamin!',
        9: 'Ephraim soll zur Verwüstung werden am Tage der Strafe. Unter den Stämmen Israels habe Ich das Wahrhaftige kundgetan.',
        10: 'Die Obersten Jehudahs sind wie die, so die Grenze verrücken; auf sie will Ich wie Wasser Mein Wüten ausschütten.',
        11: 'Bedrückt war Ephraim, zerschlagen mit Recht; denn nach dem Gebot wollte es willig wandeln.',
        12: 'Und ich bin Ephraim wie die Motte, wie der Wurmfraß dem Hause Jehudahs.',
        13: 'Und Ephraim sah seine Krankheit und Jehudah seine Wunde; und Ephraim ging nach Aschur, und sandte zum König Jareb; er aber konnte euch nicht heilen und eure Wunde nicht schließen.',
        14: 'Denn wie der Löwe bin Ich Ephraim, und wie der junge Löwe Jehudahs Hause. Ich, Ich zerfleische und gehe hin; Ich trage davon, und niemand ist, der errettet.',
        15: 'Ich gehe hin, Ich kehre zurück an Meinen Ort, bis daß sie ihre Schuld erkennen und Mein Angesicht suchen. In ihrer Angst werden sie früh nach Mir suchen.',
    },
    6: {
        1: 'Kommt, und lasset uns zurückkehren zu Jehovah; denn Er hat zerfleischt, und Er wird uns heilen; Er schlug, und Er wird uns verbinden.',
        2: 'Er macht uns lebendig nach zwei Tagen, am dritten Tage richtet Er uns auf, auf daß wir vor Ihm leben.',
        3: 'Und lasset uns erkennen, und lasset uns nachjagen, zu erkennen Jehovah; wie die Morgenröte ist bereitet Sein Ausgang, und wie der Regen kommt Er zu uns, wie der Spätregen, der das Land feuchtet.',
        4: 'Was soll Ich dir tun, Ephraim? Was soll Ich dir tun, Jehudah? Und eure Barmherzigkeit ist wie die Wolke des Mor- gens, und wie der Tau, der in der Früh fortgeht.',
        5: 'Darum haue Ich unter die Propheten und erwürge sie durch Meines Mundes Reden, und deine Gerichte sind ein Licht, das ausgeht.',
        6: 'Denn an Barmherzigkeit habe Ich Lust und nicht am Opfer, und an der Erkenntnis Gottes mehr, denn am Brandopfer.',
        7: 'Und sie haben gleich Adam den Bund übertreten, da wurden sie Mir untreu.',
        8: 'Gilead ist die Hauptstadt derer, die Missetat tun, mit Fußstapfen von Blut.',
        9: 'Und wie Kriegshaufen, die auf einen Mann harren, ist die Gesellschaft der Priester; auf dem Wege nach Schechem morden sie, denn Schandtaten tun sie.',
        10: 'Schauerliches habe Ich im Hause Israels gesehen. Da buhlt Ephraim, und Israel verunreinigt sich.',
        11: 'Auch Jehudah bringt dir eine Ernte, wenn Ich die Gefangenschaft Meines Volkes zurückwenden werde.',
    },
    7: {
        1: 'Da Ich Israel heilte, ward Ephraims Missetat aufgedeckt, und die Bosheiten Samariens, wie sie Lüge tun, und der Dieb kommt, und draußen Kriegshaufen ausrücken.',
        2: 'Und sie sagen nicht zu ihrem Herzen, Ich gedenke aller ihrer Bosheiten. Nun umgeben sie ihre Handlungen ringsumher; vor Meinem Angesichte sind sie.',
        3: 'Mit ihrer Bosheit machen den König sie froh, mit ihren Verstellungen die Obersten.',
        4: 'Sie alle sind Ehebrecher, wie ein Ofen geheizt vom Bäcker; der Kneter feiert vom Kneten des Teiges bis zu seiner Säuerung.',
        5: 'Am Tage unseres Königs erkranken die Obersten von der Glut des Weins; er reicht die Hand den Spöttern hin.',
        6: 'Wenn sie ihr Herz wie einen Ofen darbringen, während sie auflauern, die ganze Nacht schläft ihr Bäcker; am Morgen brennt es wie ein flammendes Feuer.',
        7: 'Wie der Ofen sind sie alle erhitzt; und sie fressen ihre Richter auf. All ihre Könige fallen. Da ist keiner unter ihnen, der Mich anriefe.',
        8: 'Ephraim vermengt sich mit den Völkern. Ephraim ist zu einem Kuchen geworden, der nicht umgekehrt worden.',
        9: 'Fremde fressen seine Kraft, und er weiß es nicht; Greisenhaar auch wird über ihn gesprengt, und er weiß es nicht.',
        10: 'Und der Stolz Israels antwortet wider sein Angesicht; aber sie kehren nicht zurück zu Jehovah, ihrem Gott, und suchen Ihn nicht in alle dem.',
        11: 'Und Ephraim wird wie eine dumme Taube, ohne Herz. Ägypten riefen sie, nach Aschur gingen sie.',
        12: 'Wie sie hingehen, breite Ich Mein Netz über sie aus, Ich bringe sie herab wie des Himmels Gevögel, züchtige sie, wie in ihrer Gemeinde gehört worden.',
        13: 'Wehe ihnen, daß sie von Mir entflohen; Verheerung über sie, daß sie von Mir abgefallen! Und Ich hätte sie eingelöst, aber sie redeten Falsches über Mich.',
        14: 'Und sie schrien nicht zu Mir in ihrem Herzen, wenn sie auf ihren Lagern heulten, ob dem Korn und Most. Sie rotteten sich zusammen und wichen ab von Mir.',
        15: 'Und Ich hätte sie in Zucht genommen und ihre Arme gestärkt, aber sie denken Böses wider Mich.',
        16: 'Sie wenden sich zurück, nicht nach oben; wie der trügliche Bogen sind sie. Durch das Schwert sollen ihre Obersten fallen ob dem Unwillen ihrer Zunge. Das ist ihr Hohn im Lande Ägypten.',
    },
    8: {
        1: 'An deinen Gaumen die Posaune! Wie ein Adler über das Haus des Jehovah! Weil sie Meinen Bund übertreten und von Meinem Gesetz abgefallen sind.',
        2: 'Sie werden schreien zu Mir: Mein Gott! Wir, Israel, erkennen Dich.',
        3: 'Das Gute hat Israel verworfen! Der Feind setze ihm nach!',
        4: 'Ohne Mich machten sie Könige, und Oberste, ohne daß Ich es wußte. Ihr Silber und ihr Gold machten sie sich zu Götzenbildern, auf daß Er ausgerottet werde.',
        5: 'Dein Kalb, Samaria, verwirft dich, Mein Zorn entbrennt wider sie. Wie lange vermögen sie nicht, sich unsträflich zu halten?',
        6: 'Denn aus Israel ist es, und er, der Werkmann, hat es gemacht, und kein Gott ist es. Zu Stücken wird das Kalb Samariens.',
        7: 'Denn Wind säen sie, und Sturmwind ernten sie. Eine Saat hat er nicht, und was da sproßt, gibt kein Mehl, gäbe es vielleicht, so verschlingen es die Fremden.',
        8: 'Verschlungen ist Israel; nun sind sie unter den Völkerschaften wie ein Gefäß, an dem man keine Lust hat;',
        9: 'Weil sie hinaufzogen nach Aschur, ein Waldesel, einsam für sich. Ephraim dingt sich Liebschaften.',
        10: 'Obgleich sie dingten unter den Völkerschaften, nun bringe Ich sie zusammen, und sie sollen zusammenbringen, und sie sollen anfangen sich zu mindern unter der Last des Königs der Obersten.',
        11: 'Denn Ephraim mehrte die Altäre zur Sünde; zur Sünde sind ihm die Altäre geworden.',
        12: 'Schrieb Ich ihm viele Meiner Gesetze, wie fremd wurden sie geachtet.',
        13: 'Als Schlachtopfer opfern sie Mir Gaben des Fleisches, und essen es. Jehovah hat daran kein Gefallen. Er gedenkt nun ihrer Missetat, und sucht heim ihre Sünden. Sie möchten nach Ägypten zurückkehren.',
        14: 'Und Israel vergißt Dessen, Der ihn gemacht, und baut Tempel, und Jehudah mehrt die festen Städte; Ich aber will Feuer in ihre Städte senden, und es soll seine Paläste auffressen.',
    },
    9: {
        1: 'Sei nicht froh zum Frohlocken, Israel, wie die Völker, da du von deinem Gotte fortgebuhlt; du liebtest Buhlgaben auf all deinen Tennen des Korns.',
        2: 'Tenne und Kelterkufe soll sie nicht weiden, und der Most soll sie täuschen.',
        3: 'Sie wohnen nicht im Lande Jehovahs, und Ephraim kehrt zurück nach Ägypten, und sie essen Unreines in Aschur.',
        4: 'Nicht gießen sie für Jehovah Wein aus, noch sind Ihm ihre Schlachtopfer angenehm. Wie Brot der Bekümmerten sind sie für sie; alle, so davon essen, verunreinigen sich; denn ihr Brot ist für ihre Seelen, es kommt nicht in das Haus Jehovahs.',
        5: 'Was werdet ihr tun am Tage der Feier, und am Tage des Festes Jehovahs?',
        6: 'Denn siehe, sie sind weggezogen vor der Verheerung, Ägypten wird sie zusammenbringen, Moph sie begraben, das Kleinod ihres Silbers wird die Distel einnehmen, Dornhecken sind in ihren Zelten.',
        7: 'Gekommen sind die Tage der Heimsuchung, gekommen die Tage der Vergeltung. Wissen soll Israel: ein Narr ist der Prophet, irrsinnig der Mann des Geistes ob der Menge deiner Missetat und ob der vielen Anfeindung.',
        8: 'Ephraim ist ein Wächter mit meinem Gott; der Prophet die Schlinge eines Vogelstellers auf allen seinen Wegen, Anfeindung im Hause seines Gottes.',
        9: 'Tief verdorben sind sie, wie in den Tagen Gibeahs. Er wird gedenken ihrer Missetat, wird heimsuchen ihre Sünden.',
        10: 'Wie Weinbeeren in der Wüste fand Ich Israel, wie den Erstling am Feigenbaum in ihrem Anfange sah Ich eure Väter. Nach Baal-Peor kamen sie, und da weihten sie sich der Schande und wurden abscheulich, wie ihr Lieben.',
        11: 'Ephraim: wie ein Vogel fliegt fort seine Herrlichkeit, von der Geburt, von dem Mutterleib und von der Empfängnis.',
        12: 'Ja, wenn sie ihre Söhne großziehen, so mache Ich sie kinderlos, ohne Menschen. Ja, wehe auch ihnen, wenn Ich weggehe von ihnen.',
        13: 'Ephraim, wie Ich ihn sehe bis nach Zor, ist gepflanzt in Lieblichkeit; aber Ephraim muß seine Söhne hinaus zum Würger bringen.',
        14: 'Gib ihnen, Jehovah - was sollst Du ihnen geben? - gib ihnen einen fehlgebärenden Mutterschoß und versiegende Brüste.',
        15: 'All ihre Bosheit ist in Gilgal; daselbst hasse Ich sie. Ob der Bosheit ihrer Handlungen vertreibe Ich sie aus Meinem Haus. Nicht will Ich fürderhin sie lieben. Alle ihre Obersten sind störrisch.',
        16: 'Geschlagen ist Ephraim, ihre Wurzel verdorrt, daß sie keine Frucht bringen; und ob sie erzeugen, so wollte Ich doch ihres Leibes Begehrte töten.',
        17: 'Mein Gott verschmäht sie, darum, daß sie auf Ihn nicht hörten; und sie sollen unter die Völkerschaften entfliehen.',
    },
    10: {
        1: 'Ein abgeleerter Weinstock ist Israel; seine Frucht ist gleich wie er; nach der Menge seiner Frucht mehrte er die Altäre. Nach der Güte seines Landes machte er gut die Bildsäulen.',
        2: 'Es schmeichelte ihr Herz. Nun werden sie verwüstet, Er wird zerwerfen ihre Altäre, zerscheitern ihre Bildsäulen.',
        3: 'Ja, nun sprechen sie: Wir haben keinen König, weil wir Jehovah nicht fürchten; und der König, was könnte der für uns tun?',
        4: 'Sie reden Reden, mit eitlen Eiden schlie-ßen sie einen Bund. Wie Schierling sproßt auf das Gericht auf den Furchen des Feldes.',
        5: 'Um die Kälber in Beth-Aven bangen sie, der Bewohner Schomrons; denn sein Volk trauert darum, es zittern seine Götzenpriester für seine Herrlichkeit, daß sie von ihm weggeführt wird.',
        6: 'Auch geleitet man es nach Aschur als Geschenk für den König Jareb. Scham ergreift Ephraim, und ob seinem Ratschluß schämt sich Israel.',
        7: 'Schomron ist verstört, sein König ist wie der Schaum auf des Wassers Fläche.',
        8: 'Und vernichtet werden die Opferhöhen Avens, die Sünde Israels; Dorn und Distel kommen herauf auf ihren Altären, und sie sprechen zu den Bergen: Decket uns! und zu den Hügeln: Fallet über uns!',
        9: 'Seit den Tagen Gibeahs hast du gesündigt, Israel! Da standen sie; der Streit wider die Söhne der Verkehrtheit erreichte sie nicht in Gibeah.',
        10: 'Nach Meinem Sehnen werde Ich sie züchtigen. Und versammeln sollen sich Völker wider sie, für ihre zwei Missetaten sie zu binden.',
        11: 'Und Ephraim ist eine abgerichtete Kalbe, die das Dreschen liebt; aber Ich will hinfahren über das Gute ihres Nackens und Ephraim reiten lassen; pflügen soll Jehudah und Jakob soll ihm eggen.',
        12: 'Sät euch zur Gerechtigkeit; erntet nach dem Munde der Gerechtigkeit, brechet auch den Brachacker um. Und es ist Zeit Jehovah zu suchen; bis daß Er komme und euch unterweise in der Gerechtigkeit.',
        13: 'Ihr habt Ungerechtigkeit gepflügt und Verkehrtheit geerntet, habt die Frucht der Falschheit gegessen, darum daß du auf deine Wege, auf deine vielen Helden vertrautest.',
        14: 'Und es ersteht ein Getöse unter deinen Völkern, und alle deine Festungen werden verheert, gleich der Verheerung von SchalmanBeth-Arbel am Tage des Streites, da die Mutter mit den Söhnen zerschmettert ward.',
        15: 'Solches tut euch Beth-El um des Bösen eures Bösen willen. Mit dem Morgenrot wird verstört der König von Israel.',
    },
    11: {
        1: 'Als Israel jung war, liebte Ich ihn, und aus Ägypten rief Ich Meinen Sohn.',
        2: 'So man ihnen jetzt ruft, so gehen sie fort von ihrem Angesicht, opfern den Baalen und räuchern den Schnitzbildern.',
        3: 'Ich gängelte Ephraim. Er nahm sie auf Seine Arme. Aber sie wußten nicht, daß Ich sie heilte.',
        4: 'Mit Stricken des Menschen zog Ich sie, mit Seilen der Liebe, und ward ihnen wie einer, der das Joch emporhebt über ihre Kinnbacken, und reichte ihm zu essen.',
        5: 'Nicht sollte er zurück nach dem Lande Ägypten kehren; und Aschur, der ist sein König, weil sie sich weigerten, zurückzukehren.',
        6: 'Und kreisen wird das Schwert in seinen Städten und verzehren seine Riegel und auffressen wegen ihrer Ratschläge.',
        7: 'Und Mein Volk ist es müde, zu Mir zurückzukehren. Rufen sie ihm aufwärts, so richtet sich keiner empor.',
        8: 'Wie soll Ich dich dahingeben, Ephraim? Soll Ich dich hinliefern, Israel? Soll Ich dich hingeben wie Adamah, dich setzen wie Zeboim? Mein Herz kehrt sich um in Mir; allzumal ist Meine Reue entbrannt.',
        9: 'Nicht will Ich tun nach Meines Zornes Entbrennen; will nicht zurückkehren, Ephraim zu verderben; denn ein Gott bin Ich, und nicht ein Mann. In deiner Mitte ist der Heilige; nicht will Ich kommen in die Stadt.',
        10: 'Jehovah nach werden sie gehen. Wie ein Löwe wird Er brüllen. Weil Er brüllt, werden die Söhne vom Meere einherzittern.',
        11: 'Einherzittern werden sie wie die Vögel aus Ägypten und wie die Taube aus dem Lande Aschur; und Ich werde sie wohnen lassen in ihren Häusern, spricht Jehovah.',
    },
    12: {
        1: 'Umgeben hat Mich Ephraim mit Vorstellung, und mit Trug das Haus Israel; aber Jehudah herrscht noch mit Gott, und getreu mit den Heiligen.',
        2: 'Ephraim weidet sich am Wind, und setzt dem Ostwind nach den ganzen Tag; Falschheit und Verheerung mehrt es, und sie schließen einen Bund mit Aschur, und Öl wird nach Ägypten gebracht.',
        3: 'Und einen Hader hat Jehovah mit Jehudah, und wird heimsuchen Jakob nach seinen Wegen, nach seinen Handlungen ihm es zurückgeben.',
        4: 'Im Mutterleibe hat er seinem Bruder die Ferse unterschlagen, und in seiner Vollkraft mit Gott gekämpft;',
        5: 'Und gekämpft mit dem Engel und ihn übermocht. Er weinte und erflehte ihn. In Bethel sollte er ihn finden, und daselbst mit uns reden.',
        6: 'Jehovah ist der Gott Zebaoth; Jehovah ist sein Gedächtnis.',
        7: 'Und du, kehre zurück zu deinem Gott; halte Gerechtigkeit und Gericht, und hoffe beständig auf deinen Gott.',
        8: 'Kanaan hat in seiner Hand die Waage des Betrugs, er liebt zu bedrücken.',
        9: 'Und Ephraim spricht: Wohl bin ich reich geworden, habe Wohlstand mir gefunden; aber bei all meinem Bemühen wird man an mir keine Missetat finden, die Sünde wäre.',
        10: 'Aber Ich bin Jehovah, dein Gott, vom Lande Ägypten her; Ich werde dich noch in Zelten wohnen lassen, wie in den Tagen der Festzeit;',
        11: 'Und Ich rede zu den Propheten, und Ich bin es, Der des Gesichtes viel macht, und durch der Propheten Hand Gleichnisse gebe.',
        12: 'Ist Gilead ein Aven? Sie werden zur Eitelkeit. In Gilgal opfern sie Ochsen; auch sind ihre Altäre wie Steinhaufen auf den Furchen des Feldes.',
        13: 'Und Jakobs entwich in das Gefilde Arams, und Israel diente um ein Weib, und um ein Weib hütete er.',
        14: 'Und durch einen Propheten führte Jehovah Israel herauf aus Ägypten, und durch einen Propheten ward es gehütet. Ephraim hat gereizt durch Bitterkeiten, und Er läßt sein Blut auf ihm, und sein Herr gibt ihm zurück seine Schmach.',
    },
    13: {
        1: 'Als Ephraim Schauderhaftes redete, trug er es in Israel; und er ward schuldig am Baal und starb.',
        2: 'Und jetzt tut es zur Sünde hinzu, und sie haben sich ein Gußbild gemacht von ihrem Silber, in ihrer Einsicht, Götzenbilder, gänzlich gemacht von Werkleuten. Zu sich selber sagen sie: Die, so einen Menschen opfern, sollen küssen die Kälber.',
        3: 'Daher werden sie sein wie die Wolke des Morgens und wie der Tau, der in der Früh fallend dahingeht, wie die Spreu von der Tenne verweht, und wie der Rauch aus dem Gitterfenster.',
        4: 'Bin Ich doch Jehovah, dein Gott vom Lande Ägypten her, und einen Gott außer Mir kennst du nicht; und ohne Mich ist kein Heiland.',
        5: 'Ich kannte dich in der Wüste, im Lande der Gluthitze.',
        6: 'Wie sie ihre Weide hatten, wurden sie satt, und da sie satt waren, erhöhte sich ihr Herz, so daß sie Mein vergaßen.',
        7: 'Und Ich werde ihnen sein wie ein Löwe, wie ein Pardel am Wege betrachte Ich sie.',
        8: 'Ich treffe auf sie wie ein beraubter Bär und zerreiße den Verschluß ihres Herzens und fresse sie da wie der alte Löwe; das wilde Tier des Feldes schlitzt sie auf.',
        9: 'Dein Verderben ist es, Israel, daß du wider Mich bist, wider deinen Beistand.',
        10: 'Wo ist nun dein König hin, daß er dich rette in allen deinen Städten, und deine Richter, da du doch sprachst: Gib mir einen König und Oberste?',
        11: 'Ich gebe dir einen König in Meinem Zorn und nehme ihn in Meinem Wüten.',
        12: 'Zugebunden ist Ephraims Missetat, aufbewahrt seine Sünde.',
        13: 'Es kommen Geburtsnöte der Gebärerin über es; ein unweiser Sohn ist es; er steht nicht die Zeit in der Söhne Durchbruch!',
        14: 'Aus der Hand der Hölle löse Ich sei ein; vom Tode will Ich sie erlösen. Tod, Ich will deine Pest, Hölle, Ich will dein Zerstörer sein! Reue ist vor Meinen Augen verborgen!',
        15: 'Denn ein wilder Esel ist er unter seinen Brüdern; der Ostwind, der Wind Jehovahs, kommt, aufsteigend von der Wüste, und es vertrocknet sein Born, und sein Brunnquell trocknet aus, er plündert den Schatz jeglichen köstlichen Geräts.',
    },
    14: {
        1: 'Schomron wird verwüstet, denn es war aufrührerisch wider seinen Gott; durch das Schwert werden seine Kindlein fallen, sie werden zerschmettert, und die Schwangeren werden aufgeschlitzt.',
        2: 'Kehre zurück, Israel, zu Jehovah, deinem Gott; denn du strauchelst in deiner Missetat.',
        3: 'Nehmt zu euch die Worte und kehrt zurück zu Jehovah; sprecht zu Ihm: Verzeihe alle Missetat, und nimm es gut, und laß uns entrichten die Farren unserer Lippen!',
        4: 'Aschur soll uns nicht retten, auf dem Roß wollen wir nicht reiten, und wollen nicht mehr zu unserer Hände Machwerk sagen: Unser Gott! Weil bei dir die Waise Erbarmen findet.',
        5: 'Ich heile ihren Abfall, Ich liebe sie freiwillig; denn Mein Zorn ist von ihm zurückgewendet.',
        6: 'Wie der Tau will Ich für Israel sein, erblühen soll es gleich der Lilie, und seine Wurzel schlagen, wie der Libanon.',
        7: 'Seine Zweige sollen dahingehen, und seine Majestät soll sein wie die des Ölbaums; und sein Geruch wie des Libanon.',
        8: 'Zurückkehren sollen sie, die in Seinem Schatten saßen, und beleben das Korn, und erblühen, wie der Weinstock; sein Andenken soll sein wie des Weins vom Libanon.',
        9: 'Ephraim, was sollen Mir fürder die Götzenbilder? Ich will antworten und ihm singen. Ich will sein wie die grünende Tanne. Aus Mir soll deine Frucht gefunden werden. Wer ist weise, daß er dies einsehe, einsichtsvoll, daß er es wisse? Denn gerade sind die Wege Jehovahs, und die Gerechten wandeln darauf, die Übertreter aber kommen darauf zu Fall.',
    },
}
